INSERT INTO public.problems (title, description, difficulty, topic, time_limit_ms, memory_limit_mb, test_cases, tags) VALUES ('Find Minimum in Rotated Sorted Array', 'Suppose an array of length n sorted in ascending order is rotated between 1 and n times.', 'Medium', 'Binary Search', 2000, 256, '[{"input": "[3,4,5,1,2]", "output": "1"}]', '{"array", "binary-search"}'), ('Search in Rotated Sorted Array', 'There is an integer array nums sorted in ascending order (with distinct values).', 'Medium', 'Binary Search', 2000, 256, '[{"input": "[4,5,6,7,0,1,2], 0", "output": "4"}]', '{"array", "binary-search"}'), ('Container With Most Water', 'You are given an integer array height of length n.', 'Medium', 'Two Pointers', 2000, 256, '[{"input": "[1,8,6,2,5,4,8,3,7]", "output": "49"}]', '{"array", "two-pointers"}'), ('Trapping Rain Water', 'Given n non-negative integers representing an elevation map where the width of each bar is 1, compute how much water it can trap after raining.', 'Hard', 'Two Pointers', 2000, 256, '[{"input": "[0,1,0,2,1,0,1,3,2,1,2,1]", "output": "6"}]', '{"array", "two-pointers", "dynamic-programming"}'), ('Best Time to Buy and Sell Stock', 'You are given an array prices where prices[i] is the price of a given stock on the ith day.', 'Easy', 'Sliding Window', 2000, 256, '[{"input": "[7,1,5,3,6,4]", "output": "5"}]', '{"array", "dynamic-programming"}'), ('Longest Repeating Character Replacement', 'You are given a string s and an integer k. You can choose any character of the string and change it to any other uppercase English character.', 'Medium', 'Sliding Window', 2000, 256, '[{"input": "ABAB, 2", "output": "4"}]', '{"hash-table", "string", "sliding-window"}'), ('Minimum Window Substring', 'Given two strings s and t of lengths m and n respectively, return the minimum window substring of s such that every character in t (including duplicates) is included in the window.', 'Hard', 'Sliding Window', 2000, 256, '[{"input": "ADOBECODEBANC, ABC", "output": "BANC"}]', '{"hash-table", "string", "sliding-window"}'), ('Daily Temperatures', 'Given an array of integers temperatures represents the daily temperatures, return an array answer such that answer[i] is the number of days you have to wait after the ith day to get a warmer temperature.', 'Medium', 'Stack', 2000, 256, '[{"input": "[73,74,75,71,69,72,76,73]", "output": "[1,1,4,2,1,1,0,0]"}]', '{"array", "stack", "monotonic-stack"}'), ('Largest Rectangle in Histogram', 'Given an array of integers heights representing the histogram bar height where the width of each bar is 1, return the area of the largest rectangle in the histogram.', 'Hard', 'Stack', 2000, 256, '[{"input": "[2,1,5,6,2,3]", "output": "10"}]', '{"array", "stack", "monotonic-stack"}'), ('Merge K Sorted Lists', 'You are given an array of k linked-lists lists, each linked-list is sorted in ascending order. Merge all the linked-lists into one sorted linked-list and return it.', 'Hard', 'Linked List', 2000, 256, '[{"input": "[[1,4,5],[1,3,4],[2,6]]", "output": "[1,1,2,3,4,4,5,6]"}]', '{"linked-list", "divide-and-conquer", "heap"}');